  if (['enroll','handoff'].includes(action)) need(result.has('--ref') && result.has('--out'), 'ORDER_AND_OUTPUT_REQUIRED');
  if (action === 'enroll') need(result.has('--file'), 'APPROVED_PRIVATE_FILE_REQUIRED');
