    }
    if (!['GET','HEAD'].includes(req.method)) return {status:405,body:{error:'OPERATION_READ_ONLY'},headers:{allow:'GET, HEAD'}};
    if (url.pathname === BASE) { query(url,[]); return {status:200,body:inventory()}; }
