      maxInputBytes: bound(raw.maxInputBytes ?? 262144, 1, 524288, 'maxInputBytes'),
      maxOutputBytes: bound(raw.maxOutputBytes ?? 524288, 1, 1048576, 'maxOutputBytes'),
      timeoutMs: bound(raw.timeoutMs ?? 10000, 50, 120000, 'timeoutMs'),
