  abs(x.evidenceDir, 'EVIDENCE_PATH_NOT_ABSOLUTE');
  if (x.trustedPayer !== undefined)
    need(typeof x.trustedPayer === 'string' && /^[GC][A-Z2-7]{55}$/.test(x.trustedPayer),
