      sourceSha256:edition.raw?.sha256??null,sourceKind:documentEdition?'retained-document':'http-capture',
      coverage:'UNAVAILABLE',updatesLookup:'NOT_RETAINED',
      requestedDois:[],updateRequestedDois:[],missingUpdates:[],issues:[]};
