export const QUOTE_REQUEST_LIMIT=96*1024*1024+65536;
export const QUOTE_FILE_LIMIT=256*1024*1024;
export const UUID=/^[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/;
export const SHA=/^[a-f0-9]{64}$/;
export const copy=value=>structuredClone(value);
export const fingerprint=customerUpdateDigest,same=customerUpdateSame;
export function need(ok,code='RESEARCH_QUOTE_INPUT_INVALID',status=422){
 if(!ok)throw Object.assign(new Error(code),{code,status});
}
export function fields(value,allowed,required=allowed){
 need(value!==null&&typeof value==='object'&&!Array.isArray(value)&&
  Object.keys(value).every(key=>allowed.includes(key))&&required.every(key=>Object.hasOwn(value,key)),
  'RESEARCH_QUOTE_FIELDS_INVALID');return value;
}
export function id(value){need(UUID.test(value??''),'RESEARCH_QUOTE_REQUEST_ID_REQUIRED');return value;}
export function hash(value){need(SHA.test(value??''),'RESEARCH_QUOTE_SHA256_REQUIRED');return value;}
export function alias(value){need(typeof value==='string'&&/^[a-z0-9][a-z0-9_-]{0,63}$/.test(value),'RESEARCH_QUOTE_PROFILE_REQUIRED');return value;}
export function text(value,max=240,{empty=false}={}){
 need(typeof value==='string'&&value.length<=max&&(empty||value.trim())&&
  !/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/.test(value),'RESEARCH_QUOTE_TEXT_REQUIRED');return value;
}
export function dossier(value){need(/^d_[a-f0-9-]{36}$/.test(value??''),'DOSSIER_ID_INVALID');return value;}
export function page(input={}){
 fields(input,['offset','limit','snapshot','dossierId','kind'],[]);
 const value={offset:input.offset??0,limit:input.limit??50,...copy(input)};
 need(Number.isSafeInteger(value.offset)&&value.offset>=0&&Number.isSafeInteger(value.limit)&&value.limit>=1&&value.limit<=100,
  'RESEARCH_QUOTE_PAGE_INVALID');
 if(value.snapshot!==undefined)hash(value.snapshot);
 if(value.dossierId!==undefined)dossier(value.dossierId);
 if(value.kind!==undefined)need(['CASE','BRIEF','RESPONSE','PUBLICATION','REALIZED'].includes(value.kind),'RESEARCH_QUOTE_KIND_INVALID');
 return value;
}
export function briefSelection(input){
 fields(input,['requestId','caseId','caseRevision','quoteId','quoteSha256','dossierId','revision','projectId','briefId',
  'merchant','scope','reason','actor']);
 id(input.requestId);id(input.caseId);hash(input.caseRevision);id(input.quoteId);hash(input.quoteSha256);
 dossier(input.dossierId);customerRevision(input.revision);customerIdentifier(input.projectId);customerIdentifier(input.briefId);
 alias(input.merchant);text(input.reason,20000);
 fields(input.scope,['component','unit','note']);
 need(['IMPLEMENTATION','RECURRING','ROUTE_USAGE','KEEP'].includes(input.scope.component),'RESEARCH_QUOTE_SCOPE_COMPONENT_REQUIRED');
 text(input.scope.unit,240,{empty:input.scope.component==='KEEP'});text(input.scope.note,16000,{empty:true});
 return {...copy(input),actor:customerActor(input.actor)};
}
export function responseSelection(input){
 fields(input,['requestId','bindingId','caseRevision','responseId','revision','actor','by']);
 id(input.requestId);id(input.bindingId);hash(input.caseRevision);id(input.responseId);customerRevision(input.revision);
 return {...copy(input),actor:customerActor(input.actor),by:customerActor(input.by)};
}
export function normalizePublicationSelection(input){
 fields(input,['requestId','bindingId','dossierId','revision','deliveryId','title','summary','usage','sourceWorkspace'],
  ['requestId','bindingId','dossierId','revision','deliveryId','title','summary','usage']);
 id(input.bindingId);
 const {bindingId,...native}=input;
 const selected=publicationRequest({...copy(native),merchant:'selected'});
 const {merchant,...result}=selected;return {...result,bindingId};
}
export function realizedSelection(input){
 fields(input,['requestId','bindingId','publicationId','purchaseIds','revision','pricing','actor']);
 id(input.requestId);id(input.bindingId);id(input.publicationId);customerRevision(input.revision);
 need(Array.isArray(input.purchaseIds)&&input.purchaseIds.length<=100,'RESEARCH_QUOTE_PURCHASE_SELECTION_INVALID');
 input.purchaseIds.forEach(id);need(new Set(input.purchaseIds).size===input.purchaseIds.length,'RESEARCH_QUOTE_PURCHASE_SELECTION_INVALID');
 if(input.pricing!==null){
  fields(input.pricing,['profile','version','costEdition'],['profile','version']);
  alias(input.pricing.profile);id(input.pricing.version);if(input.pricing.costEdition!==undefined)id(input.pricing.costEdition);
 }
 return {...copy(input),actor:customerActor(input.actor)};
}
export function caseSelection(input){
 fields(input,['requestId','caseId','dossierId','revision','projectId','briefId','actor']);
 id(input.requestId);id(input.caseId);dossier(input.dossierId);customerRevision(input.revision);
 customerIdentifier(input.projectId);customerIdentifier(input.briefId);
 return {...copy(input),actor:customerActor(input.actor)};
}
export function applySelection(input){fields(input,['id','reviewSha256']);id(input.id);hash(input.reviewSha256);return copy(input);}
export function sourceDescriptor(name,body){
 need(body instanceof Uint8Array,'RESEARCH_QUOTE_FILE_REQUIRED');
 return {name,bytes:body.length,sha256:createHash('sha256').update(body).digest('hex')};
}
export function reviewedBrief(original,quote,scope,reference){
 const next=customerBrief(copy(original));
 if(scope.component==='KEEP')return next;
 const amount={IMPLEMENTATION:quote.totals.implementationUsd,RECURRING:quote.totals.recurringUsd,
  ROUTE_USAGE:quote.totals.routeUsageUsd}[scope.component];
 need(typeof amount==='string'&&/^(0|[1-9]\d*)(?:\.\d{1,6})?$/.test(amount),'RESEARCH_QUOTE_NATIVE_AMOUNT_REQUIRED');
 next.scope={currency:quote.totals.currency,amount,unit:scope.unit,note:scope.note,reference};
 return customerBrief(next);
}
export const nativeRequestId=(id,kind)=>'rq-'+kind.toLowerCase()+'-'+id;
export const serialized=value=>Buffer.from(JSON.stringify(customerJson(value),null,2)+'\n');

// MIT. Quote operations retain complete native inputs with the original private writer.
import {readdir} from 'node:fs/promises';
import {join} from 'node:path';
import {exists,digest} from '../../node/store.mjs';
import {readResearchHostFile,openResearchSource} from '../workspace-files.mjs';
import {customerDirectory,withCustomerOperation,readCustomerJson,retainCustomerBytes,retainCustomerJson}
 from '../customer-updates/files.mjs';
import {QUOTE_OPERATION_SCHEMA,QUOTE_FILE_LIMIT,id,need,copy,same,fingerprint,page} from './contracts.mjs';
export {customerDirectory,withCustomerOperation,readCustomerJson,retainCustomerBytes,retainCustomerJson,exists};
export const now=()=>new Date().toISOString();
export async function optional(root,name,limit=QUOTE_FILE_LIMIT){
 const path=join(root,name);return await exists(path)?(await readCustomerJson(path,limit)).value:null;
}
export function operationPath(root,requestId){id(requestId);return join(root,'operations',requestId);}
export async function quoteRoot(directory){
 const root=await customerDirectory(directory);await customerDirectory(join(root,'operations'));return root;
}
export async function retainQuoteRequest(root,{kind,input,workspaceId,casesWorkspaceId}){
 const old=await optional(root,'request.json');
 if(old){
  need(old.schema===QUOTE_OPERATION_SCHEMA&&old.kind===kind&&old.workspaceId===workspaceId&&
   old.casesWorkspaceId===casesWorkspaceId&&old.requestSha256===fingerprint(old.request)&&same(old.request,input),
   'RESEARCH_QUOTE_REQUEST_CHANGED',409);return old;
 }
 const record={schema:QUOTE_OPERATION_SCHEMA,kind,workspaceId,casesWorkspaceId,id:input.requestId,
  request:copy(input),requestSha256:fingerprint(input),createdAt:now()};
 await retainCustomerJson(root,'request.json',record);return record;
}
export async function readQuoteOperation(root){
 const request=await optional(root,'request.json'),review=await optional(root,'review.json'),result=await optional(root,'result.json');
 need(request?.schema===QUOTE_OPERATION_SCHEMA&&request.id===request.request?.requestId&&
  request.requestSha256===fingerprint(request.request),'RESEARCH_QUOTE_REQUEST_CHANGED');
 if(review)need(review.requestSha256===request.requestSha256&&review.reviewSha256===fingerprint(review.proof),
  'RESEARCH_QUOTE_REVIEW_CHANGED');
 if(result)need(result.requestSha256===request.requestSha256&&result.reviewSha256===(review?.reviewSha256??null)&&
  result.resultSha256===fingerprint(result.result),'RESEARCH_QUOTE_RESULT_CHANGED');
 return {request,review,result};
}
export function operationView(record){
 return {schema:QUOTE_OPERATION_SCHEMA,workspaceId:record.request.workspaceId,casesWorkspaceId:record.request.casesWorkspaceId,
  id:record.request.id,kind:record.request.kind,status:record.result?'COMPLETE':record.review?'REVIEWED':'PREPARING',
  request:copy(record.request.request),requestSha256:record.request.requestSha256,createdAt:record.request.createdAt,
  review:record.review?{reviewSha256:record.review.reviewSha256,...copy(record.review.proof)}:null,
  result:copy(record.result?.result??null)};
}
export async function saveQuoteReview(root,record,proof){
 const review={requestSha256:record.requestSha256,proof:copy(proof),reviewSha256:fingerprint(proof),createdAt:now()};
 await retainCustomerJson(root,'review.json',review);return review;
}
export async function saveQuoteResult(root,record,review,result){
 const envelope={requestSha256:record.requestSha256,reviewSha256:review?.reviewSha256??null,
  result:copy(result),resultSha256:fingerprint(result),completedAt:now()};
 await retainCustomerJson(root,'result.json',envelope);return envelope;
}
export async function verifyQuoteFiles(root,files){
 need(Array.isArray(files)&&files.length<=100,'RESEARCH_QUOTE_FILES_INVALID');
 const names=new Set();
 for(const file of files){
  need(/^[A-Za-z0-9][A-Za-z0-9._-]{0,179}$/.test(file.name??'')&&!names.has(file.name)&&
   Number.isSafeInteger(file.bytes)&&file.bytes>0&&file.bytes<=QUOTE_FILE_LIMIT&&/^[a-f0-9]{64}$/.test(file.sha256??''),
   'RESEARCH_QUOTE_FILE_INVALID');
  names.add(file.name);
  const body=await readResearchHostFile(join(root,file.name),file.bytes);
  need(body.length===file.bytes&&digest(body)===file.sha256,'RESEARCH_QUOTE_FILE_CHANGED');
 }
 return files;
}
export async function quoteInventory(root,query={}){
 const selected=page(query),items=[],errors=[],names=(await readdir(join(root,'operations'))).filter(name=>/^[a-f0-9-]{36}$/.test(name)).sort();
 need(names.length<=10000,'RESEARCH_QUOTE_OPERATION_LIMIT');
 for(const requestId of names)try{
  const directory=operationPath(root,requestId),request=await optional(directory,'request.json');
  if(!request)continue;
  need(request.schema===QUOTE_OPERATION_SCHEMA&&request.requestSha256===fingerprint(request.request),'RESEARCH_QUOTE_REQUEST_CHANGED');
  const result=await optional(directory,'result.json'),hasReview=await exists(join(directory,'review.json'));
  const dossierId=request.request.dossierId??result?.result?.dossierId??null;
  if(selected.dossierId&&selected.dossierId!==dossierId||selected.kind&&selected.kind!==request.kind)continue;
  items.push({id:requestId,kind:request.kind,createdAt:request.createdAt,dossierId,
   caseId:request.request.caseId??result?.result?.caseId??null,quoteId:request.request.quoteId??null,
   status:result?'COMPLETE':hasReview?'REVIEWED':'PREPARING',bindingId:request.request.bindingId??null});
 }catch(error){errors.push({id:requestId,code:error.code??'RESEARCH_QUOTE_OPERATION_UNAVAILABLE'});}
 items.sort((a,b)=>b.createdAt.localeCompare(a.createdAt)||a.id.localeCompare(b.id));
 const snapshot=fingerprint({items,errors});
 need(selected.snapshot===undefined||selected.snapshot===snapshot,'RESEARCH_QUOTE_INVENTORY_CHANGED',409);
 need(selected.offset<=items.length,'RESEARCH_QUOTE_PAGE_INVALID');
 const part=items.slice(selected.offset,selected.offset+selected.limit),next=selected.offset+part.length;
 return {schema:QUOTE_OPERATION_SCHEMA,snapshot,items:part,errors,offset:selected.offset,limit:selected.limit,
  total:items.length,nextOffset:next<items.length?next:null};
}
export async function quoteOperationFiles(root){
 const record=await readQuoteOperation(root),expected=record.review?.proof?.files??[],files=[],names=new Set();
 need(Array.isArray(expected)&&expected.length<=100,'RESEARCH_QUOTE_FILES_INVALID');
 for(const file of expected){
  need(/^[A-Za-z0-9][A-Za-z0-9._-]{0,179}$/.test(file.name??'')&&!names.has(file.name)&&
   Number.isSafeInteger(file.bytes)&&file.bytes>0&&file.bytes<=QUOTE_FILE_LIMIT&&/^[a-f0-9]{64}$/.test(file.sha256??''),
   'RESEARCH_QUOTE_FILE_INVALID');
  names.add(file.name);files.push({...file,contentType:file.name.endsWith('.md')?'text/markdown; charset=utf-8':
   file.name.endsWith('.tar')?'application/x-tar':'application/json; charset=utf-8'});
 }
 for(const name of ['request.json',...(record.review?['review.json']:[]),...(record.result?['result.json']:[])]){
  need(!names.has(name),'RESEARCH_QUOTE_RESERVED_FILE_CHANGED');
  const original=await readCustomerJson(join(root,name),QUOTE_FILE_LIMIT);
  files.push({name,bytes:original.bytes,sha256:original.sha256,contentType:'application/json; charset=utf-8'});
 }
 return {record,files};
}
export async function openQuoteFile(root,name){
 const {files}=await quoteOperationFiles(root),file=files.find(row=>row.name===name);
 need(file,'RESEARCH_QUOTE_FILE_NOT_FOUND',404);
 const source=await openResearchSource(join(root,name),file.bytes,{sha256:file.sha256});
 return {...source,name:file.name,contentType:file.contentType};
}

// MIT. Inspect the original quotation configuration and sources before managed launch.
import {lstat,realpath} from 'node:fs/promises';
import {dirname,basename,join} from 'node:path';
import {readResearchQuoteConfiguration,selectQuotePricing,assertQuoteDirectory,quotePath} from './configuration.mjs';
import {need,copy,same,fingerprint,hash} from './contracts.mjs';

export const RESEARCH_QUOTE_LAUNCH_SCHEMA='sf88-research-customer-quote-launch/v1';

/** Inspect a directory selection without creating any part of its native state. */
async function location(role,value,{privateTarget=false}={}){
 const path=quotePath(value),missing=[];let selected=path;
 for(;;){
  let stat;
  try{stat=await lstat(selected);}catch(error){
   if(error.code!=='ENOENT')throw error;
   need(selected!==dirname(selected),'RESEARCH_QUOTE_LOCATION_PARENT_REQUIRED');
   missing.unshift(basename(selected));selected=dirname(selected);continue;
  }
  need(stat.isDirectory()&&!stat.isSymbolicLink()&&await realpath(selected)===selected,
   'RESEARCH_QUOTE_LOCATION_CHANGED');
  if(!missing.length&&privateTarget)
   need(process.platform==='win32'||(stat.mode&0o077)===0,'RESEARCH_QUOTE_PRIVATE_CASE_DIRECTORY_REQUIRED');
  return {role,path,exists:missing.length===0,missing,
   anchor:{path:selected,device:String(stat.dev),inode:String(stat.ino)}};
 }
}
function reviewContent(binding,locations){
 const rows=[
  {label:'Research quotation directory',value:binding.directory},
  {label:'Original case store',value:binding.casesDirectory},
  {label:'Case store on this host',value:locations.find(row=>row.role==='case-store').exists?'Existing original store':'Created by the original case writer at launch'},
  {label:'Quotation configuration',value:binding.configurationFile??'Original empty-profile defaults'},
  {label:'Pricing profiles',value:binding.pricing.length},
 ];
 const sections=[{title:'Customer operation',rows}];
 for(const profile of binding.pricing){
  const native=profile.options,values=[
   {label:'Profile',value:profile.profile},{label:'Label',value:profile.label},
   {label:'Original pricing workspace',value:profile.directory.path},
   {label:'Observed source',value:native.snapshot?'Snapshot':'Saved history'},
  ];
  for(const file of profile.files)values.push({label:file.kind+' source',value:[
   file.path,String(file.bytes)+' bytes','SHA-256 '+file.sha256]});
  for(const key of ['nativeOutbox','sourcePackage','releaseStore'])
   if(native[key])values.push({label:key,value:native[key]});
  if(native.releaseRuntime!==undefined)
   values.push({label:'Release options',value:'The complete original native runtime options are retained.'});
  sections.push({title:profile.label,collapsed:binding.pricing.length>2,rows:values});
 }
 return {schema:'stellar-forge.application-review-content.v1',title:'Research customer quotations',
  summary:'The same customer case, observed pricing sources and Research history continue through quotation, commissioned work, paid publication and receiving.',
  sections};
}

/**
 * directory is the original <Research directory>/customer-quotes directory.
 * This reader opens no case store or pricing model and acquires no writer.
 * Mutable case/history contents and not-yet-created directories are deliberately
 * outside the startup digest: their original writers can finish first launch and
 * recover it. Applications separately pins their actual selected path identities.
 */
export async function inspectResearchQuoteLaunch({directory,configurationFile=null}={}){
 const root=quotePath(directory),configuration=await readResearchQuoteConfiguration(configurationFile,{directory:root}),
  pricing=[];
 for(const profile of Object.keys(configuration.pricing).sort()){
  const selected=await selectQuotePricing(configuration,profile);pricing.push(copy(selected.binding));
 }
 const locations=[await location('quote-workspace',root),
  await location('case-store',configuration.casesDirectory,{privateTarget:true})];
 for(const profile of pricing){
  await assertQuoteDirectory(profile.directory);
  locations.push({role:'pricing:'+profile.profile,path:profile.directory.path,exists:true,missing:[],
   anchor:copy(profile.directory)});
 }
 // A host file changed during the complete source read must be reviewed again.
 const current=await readResearchQuoteConfiguration(configuration.file,{directory:root});
 need(same(configuration,current),'RESEARCH_QUOTE_LAUNCH_CONFIGURATION_CHANGED',409);
 const binding={schema:RESEARCH_QUOTE_LAUNCH_SCHEMA,directory:root,
  configurationFile:configuration.file,configurationSha256:configuration.sha256,
  casesDirectory:configuration.casesDirectory,pricing};
 const bindingSha256=fingerprint(binding);
 return {schema:RESEARCH_QUOTE_LAUNCH_SCHEMA,binding,bindingSha256,
  configuration:copy(configuration),locations,review:reviewContent(binding,locations)};
}
export function assertResearchQuoteLaunch(inspection,expectedBindingSha256){
 hash(expectedBindingSha256);
 need(inspection?.schema===RESEARCH_QUOTE_LAUNCH_SCHEMA&&inspection.binding?.schema===RESEARCH_QUOTE_LAUNCH_SCHEMA&&
  inspection.bindingSha256===fingerprint(inspection.binding)&&inspection.bindingSha256===expectedBindingSha256,
  'RESEARCH_QUOTE_LAUNCH_SOURCE_CHANGED',409);
 return inspection;
}

/** Nonsecret selected source data for the original authenticated client and ready line. */
export function researchQuoteLaunchView(inspection){
 if(inspection===null||inspection===undefined)return null;
 assertResearchQuoteLaunch(inspection,inspection.bindingSha256);
 return {schema:RESEARCH_QUOTE_LAUNCH_SCHEMA,bindingSha256:inspection.bindingSha256,
  directory:inspection.binding.directory,configurationFile:inspection.binding.configurationFile,
  configurationSha256:inspection.binding.configurationSha256,casesDirectory:inspection.binding.casesDirectory,
  profiles:inspection.binding.pricing.map(profile=>({id:profile.profile,label:profile.label,
   directory:profile.directory.path,files:copy(profile.files)}))};
}

// MIT. Native quote amounts and research records remain their original complete values.
import {customerBrief,customerUpdateInput} from '../customer-updates/contracts.mjs';
import {QUOTES_SCHEMA,copy,same,need,fingerprint,reviewedBrief,nativeRequestId} from './contracts.mjs';
export function quoteReference(caseId,quote){return 'urn:stellar-forge:merchant-quote:'+caseId+':'+quote.id+':'+quote.sha256;}
export function researchQuoteBrief(input,{workspaceId,casesWorkspaceId,caseRecord,quote,project,brief,merchant,files}){
 need(quote.id===input.quoteId&&quote.sha256===input.quoteSha256&&caseRecord.id===input.caseId&&caseRecord.revision===input.caseRevision,
  'RESEARCH_QUOTE_SELECTED_CASE_CHANGED',409);
 need(project.id===input.projectId&&brief.id===input.briefId&&brief.projectId===project.id,
  'RESEARCH_QUOTE_SELECTED_BRIEF_CHANGED',409);
 need(project.customer.id===brief.definition.customer.id,'RESEARCH_QUOTE_CUSTOMER_CHANGED',409);
