    need(result && typeof result.bytes === 'function' && result.delivery?.status === 'SAVED', 'ORIGINAL_SF88_RESULT_REQUIRED');
    need(typeof intentId === 'string' && intentId.length > 0, 'ORIGINAL_INTENT_REQUIRED');
