  need(named(editionId) && typeof questionId === 'string', 'OPENALEX_IMPORT_TARGET_REQUIRED');
  need(onPage === undefined || typeof onPage === 'function', 'OPENALEX_IMPORT_CALLBACK_INVALID');
  signal?.throwIfAborted();
