.citation-review h2 { font-size:1.18rem; line-height:1.45; }
.citation-review h3 { font-size:1rem; line-height:1.45; margin:0 0 12px; }
.citation-review h4 { font-size:.95rem; line-height:1.45; margin:0 0 8px; }
