button:hover{background:#ededed}button:disabled{color:#777;background:#eee;cursor:default}button.primary{background:#262626;color:#fff;border-color:#262626}
input,select,textarea{background:white;border:1px solid #9c9c9c;border-radius:2px;padding:7px;width:100%;min-height:36px;color:inherit}
textarea{resize:vertical;min-height:86px}input[type=checkbox]{width:18px;height:18px;min-height:18px;flex:none}
input:focus,select:focus,textarea:focus,button:focus-visible,a:focus-visible{outline:2px solid #222;outline-offset:2px}
label{display:flex;flex-direction:column;gap:5px;font-size:13px;font-weight:600;min-width:0}label.check{flex-direction:row;align-items:flex-start;font-weight:400}
label small{font-weight:400;color:#555}fieldset{border:0;margin:0;padding:0;min-width:0}.connection,.toolbar,.actions{display:flex;gap:12px;align-items:flex-end;flex-wrap:wrap}
.connection{justify-content:space-between}.connection form{display:flex;gap:8px;align-items:flex-end}.connection input{width:300px}
