th{font-weight:600;background:#eee;position:sticky;top:0}td .actions{gap:6px}.id,code{font:12px/1.5 ui-monospace,monospace;overflow-wrap:anywhere}
pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#f5f5f5;border:1px solid #ddd;padding:12px;max-height:450px;overflow:auto;font:12px/1.5 ui-monospace,monospace}
details{margin:10px 0}summary{cursor:pointer}.counts{display:flex;gap:24px;flex-wrap:wrap;border-bottom:1px solid #ccc;padding:12px 0;margin-bottom:16px}
.counts span{display:flex;flex-direction:column}.counts strong{font-size:21px}.actions{margin-top:16px}.spacer{margin-top:24px}.empty{padding:24px;border:1px dashed #aaa;color:#555}
