@media(max-width:780px){header{display:block}.grid{grid-template-columns:1fr}header,main,footer{padding:18px}.connection form{width:100%}.connection input{width:100%}.toolbar>label{min-width:100%}#panel{padding:16px}}

// MIT. Complete customer-update operator on the original Research listener.
