    return [wrap,row.label,node('span',row.kind+' · '+row.path,'id'),button('Read full record',async()=>{
      const selected=await api(rootPath()+'/record',{body:{revision:catalog.revision,path:row.path,sha256:row.sha256},readOnly:true});
