    if(kind==='retain'){
      const output=array(value.outputOptions).find(row=>JSON.stringify([row.fileId,row.nodeId??null])===$('output-option').value);
      if(!output)throw failure('PIPELINE_OUTPUT_SELECTION_REQUIRED','Select an observed output.');
      input.fileId=output.fileId;input.nodeId=output.nodeId??null;
    }
    return {operationId:value.plan.id,kind,input,status:'pending',savedAt:new Date().toISOString()};
  }
  async function dispatchAction(entry){
    const ctx=context(),token=state.opEpoch,id=entry.operationId;
    putRecord(ctx,'controls',entry);renderActionHistory();$('action-history').value=entry.input.requestId;renderActionHistory();updateBusy();
    let result;
    try{result=await api(endpoint(ctx,'/operations/'+encodeURIComponent(id)+'/'+entry.kind),{method:'POST',body:entry.input});}
    catch(error){
      if(unsentActionCodes.has(error.code)){entry={...entry,status:'review_required',error:{code:error.code,message:friendly(error)}};putRecord(ctx,'controls',entry);}
      throw error;
    }
    const original=result.actionResult;
    if(original?.requestId!==entry.input.requestId||original.kind!==entry.kind||original.status!=='COMPLETE')
      throw failure('PIPELINE_ACTION_RESULT_REQUIRED','The exact saved action result was absent.');
    entry={...entry,status:'complete',actionResult:original,completedAt:new Date().toISOString()};putRecord(ctx,'controls',entry);
    if(!opLive(ctx,token,id))return;
    applyOperation(result,{preserveReview:true});$('action-history').value=entry.input.requestId;renderActionHistory();
    notify(original.error?'The original action completed with '+(original.error.code||'a provider error')+'. Review its saved result.':
      (result.replayed?'Recovered the original '+entry.kind+' result.':'Saved '+entry.kind+' result.'),original.error?'error':'info');
  }
  async function readProviderJobs(){
    const ctx=context(),token=state.opEpoch,id=state.operationId;if(!id)return;
    const body={};if($('workflow').value)body.workflowId=validText($('workflow').value,512,'Workflow ID');
    if($('job-status').value)body.status=$('job-status').value;
    const result=await api(endpoint(ctx,'/operations/'+encodeURIComponent(id)+'/provider-jobs'),{method:'POST',body});
    if(!opLive(ctx,token,id))return;
    state.jobs=result;renderProviderJobs();updateBusy();
  }
  async function receive(){
    const ctx=context(),value=state.review,dossier=currentDossier(ctx);
    if(!value||value.retained)throw failure('PIPELINE_ORIGINAL_OUTPUT_SELECTION_REQUIRED','Choose an original retained output.');
    const pending=pendingReceives();if(pending.length){await dispatchReceive(ctx,copy(pending[0]));return;}
    const entry={status:'pending',savedAt:new Date().toISOString(),input:{requestId:uuid('receive'),selection:copy(value.selection),
      expectedEditionSha256:value.editionSha256,questionId:validText($('receive-question').value,160,'Research question'),
      label:validText($('receive-label').value,240,'Edition label'),expectedRevision:dossier.revision}};
    await dispatchReceive(ctx,entry);
  }
  async function dispatchReceive(ctx,entry){
    const token=state.selectionEpoch,selected=state.selection?copy(state.selection):null;
    putRecord(ctx,'receives',entry);
    let result;
    try{result=await api(endpoint(ctx,'/receive'),{method:'POST',body:entry.input});}
    catch(error){
      if(error.code==='REVISION_CONFLICT'){entry={...entry,status:'review_required',error:{code:error.code,message:friendly(error)}};putRecord(ctx,'receives',entry);}
      throw error;
    }
    const receipt=result.receipt;
    if(receipt?.requestId!==entry.input.requestId||receipt.dossierId!==ctx.id||receipt.questionId!==entry.input.questionId||
      receipt.editionSha256!==entry.input.expectedEditionSha256)
      throw failure('PIPELINE_RECEIVING_RECEIPT_MISMATCH','The reply did not identify this exact receiving decision.');
    putRecord(ctx,'receives',{...entry,status:'complete',receipt,completedAt:new Date().toISOString()});
    if(!live(ctx))return;
    await onReceived(result.dossier);if(!live(ctx))return;
    await loadList();if(!live(ctx))return;
    if(token===state.selectionEpoch&&same(selected,state.selection))await openOutput({editionId:receipt.editionId});
    notify((result.replayed?'Recovered the original receiving result':'Research edition received')+' at dossier revision '+receipt.revision+'.');
  }
  async function saveDownload(response,fallback,stillSelected){
    const blob=await response.blob();if(!stillSelected())return;
    const url=URL.createObjectURL(blob),link=node('a');
    const name=/filename="([^"]+)"/.exec(response.headers.get('content-disposition')||'')?.[1];
    link.href=url;link.download=name||fallback;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);
  }
  async function downloadInput(id,input){
    const ctx=context(),token=state.opEpoch;
    const response=await api(endpoint(ctx,'/operations/'+encodeURIComponent(id)+'/inputs/'+encodeURIComponent(input.id)),{download:true});
    await saveDownload(response,input.filename,()=>opLive(ctx,token,id));
  }
  async function downloadRetainedOutput(id,output){
    const ctx=context(),token=state.opEpoch;
    const response=await api(endpoint(ctx,'/operations/'+encodeURIComponent(id)+'/outputs/'+encodeURIComponent(output.id)),{download:true});
    await saveDownload(response,'pipeline.output',()=>opLive(ctx,token,id));
  }
  async function downloadOutput(file){
    const ctx=context(),token=state.selectionEpoch,value=state.review;if(!value)return;
    const response=await api(endpoint(ctx,'/download'),{method:'POST',download:true,
      body:{selection:value.selection,expectedEditionSha256:value.editionSha256,file}});
    await saveDownload(response,file==='edition'?'pipeline.research.json':'pipeline.output',()=>selectionLive(ctx,token,value.selection));
  }
  function updateBusy(){
    const busy=!!isBusy()||state.busy>0||!state.id;
    root.querySelectorAll('button,input,select,textarea').forEach(control=>{control.disabled=busy;});
    objectPanel?.updateBusy(busy);
    if(busy)return;
    const value=state.operation,op=value?.operation,configured=state.configured;
    for(const id of ['profile','question','label'])$(id).disabled=!configured||!!preparation();
    $('files').disabled=!configured;$('prepare').disabled=!configured||!$('files').files?.length;
    $('recover-prepare').disabled=!configured||!preparation();$('new-prepare').disabled=!configured||!preparation();
    $('more').disabled=!state.next;
    const available=!!value&&configured&&value.sourceMatches&&!value.running&&!pendingControls(value.plan.id).length;
    $('review-plan').disabled=!available||!value?.profileMatches||!['PREPARED','REJECTED'].includes(op?.phase)||op?.providerJobId!==null;
    $('submit').disabled=$('review-plan').disabled||!$('review-plan').checked;
    $('reload-job').disabled=!value||!configured;
    $('refresh-job').disabled=!available||!op.providerJobId;
    $('cancel').disabled=!available||op?.phase!=='ACTIVE'||!$('cancel-reason').value.trim();
    $('cancel-reason').disabled=!available||op?.phase!=='ACTIVE';
    $('provider-jobs').disabled=!value||!configured||!value.sourceMatches||value.running;
    for(const id of ['workflow','job-status'])$(id).disabled=$('provider-jobs').disabled;
    $('provider-job').disabled=!available||!array(state.jobs?.jobs).length;
    const job=array(state.jobs?.jobs).find(row=>row.id===$('provider-job').value);
    $('reconcile').disabled=!available||!job||!(op?.providerJobId===job.id||(!op?.providerJobId&&op?.phase==='SUBMISSION_UNKNOWN'))||!$('reconcile-reason').value.trim();
    $('reconcile-reason').disabled=!available||!job;
    const histories=array(state.journal?.controls).filter(row=>row.operationId===state.operationId);
    $('action-history').disabled=!histories.length;
    $('reopen-action').disabled=!configured||!value||value.running||!histories.some(row=>row.input.requestId===$('action-history').value);
    $('output-option').disabled=!available||!array(value?.outputOptions).length;
    $('retain-output').disabled=$('output-option').disabled;
    const reviewing=!!state.review,receivable=reviewing&&!state.review.retained&&configured&&!pendingReceives().length;
    $('receive').disabled=!receivable||!$('receive-question').value||!$('receive-label').value.trim();
    for(const id of ['receive-question','receive-label'])$(id).disabled=!receivable;
    root.querySelectorAll('[data-pipeline-download]').forEach(button=>{button.disabled=!reviewing;});
    for(const id of ['page','type','query','apply-filter'])$(id).disabled=!reviewing;
    $('prev').disabled=!reviewing||!state.records||state.offset===0;
    $('next').disabled=!reviewing||!Number.isSafeInteger(state.records?.nextOffset);
    root.querySelectorAll('#pipelines-recovery button').forEach(button=>{button.disabled=!configured;});
  }
  function resetScope(id){
    state.id=id;state.epoch++;state.listEpoch++;state.operations=[];state.editions=[];state.next=null;
    state.journal=readJournal({...context(),journal:null});selectOperation(null);
    $('files').value='';$('label').value='';renderConfiguration();renderRecovery();renderList();updateBusy();
  }
  $('refresh').addEventListener('click',()=>withAction(refresh));
  $('more').addEventListener('click',()=>withAction(()=>loadList(true)));
  $('files').addEventListener('change',()=>{renderFiles();updateBusy();});
  $('prepare-form').addEventListener('submit',event=>{event.preventDefault();withAction(prepare,event.currentTarget);});
  $('recover-prepare').addEventListener('click',()=>withAction(()=>recoverPreparation()));
  $('new-prepare').addEventListener('click',()=>withAction(async()=>{
    const ctx=context(),p=preparation();if(!p)return;
    const found=await recoverPreparation({allowMissing:true});if(found)return;
    needLive(ctx);clearPreparation(ctx,p);$('label').value='';renderConfiguration();notify('No published plan matched '+p.input.requestId+'. Review the files and scope for a new preparation.');
  }));
  $('review-plan').addEventListener('change',updateBusy);
  $('submit').addEventListener('click',()=>withAction(()=>dispatchAction(actionEntry('submit'))));
  $('reload-job').addEventListener('click',()=>withAction(reloadOperation));
  $('refresh-job').addEventListener('click',()=>withAction(()=>dispatchAction(actionEntry('refresh'))));
  $('cancel-form').addEventListener('submit',event=>{event.preventDefault();withAction(()=>dispatchAction(actionEntry('cancel')),event.currentTarget);});
  $('provider-form').addEventListener('submit',event=>{event.preventDefault();withAction(readProviderJobs,event.currentTarget);});
  $('provider-job').addEventListener('change',()=>{renderProviderJobs();updateBusy();});
  $('reconcile-form').addEventListener('submit',event=>{event.preventDefault();withAction(()=>dispatchAction(actionEntry('reconcile')),event.currentTarget);});
  $('action-history').addEventListener('change',()=>{renderActionHistory();updateBusy();});
  $('reopen-action').addEventListener('click',()=>withAction(async()=>{
    const entry=array(state.journal?.controls).find(row=>row.operationId===state.operationId&&row.input.requestId===$('action-history').value);
    if(entry)await dispatchAction({...copy(entry),status:'pending'});
  }));
  $('retain-form').addEventListener('submit',event=>{event.preventDefault();withAction(()=>dispatchAction(actionEntry('retain')),event.currentTarget);});
  $('receive-form').addEventListener('submit',event=>{event.preventDefault();withAction(receive,event.currentTarget);});
  for(const id of ['cancel-reason','reconcile-reason','receive-label','receive-question','question','profile','label'])
    $(id).addEventListener('input',updateBusy);
  $('filter').addEventListener('submit',event=>{event.preventDefault();withAction(async()=>{
    state.offset=0;state.filters={page:$('page').value,type:$('type').value,query:$('query').value};
    $('element-detail').hidden=true;await loadElements();
  });});
  $('prev').addEventListener('click',()=>withAction(async()=>{state.offset=Math.max(0,state.offset-25);$('element-detail').hidden=true;await loadElements();}));
  $('next').addEventListener('click',()=>withAction(async()=>{if(Number.isSafeInteger(state.records?.nextOffset)){state.offset=state.records.nextOffset;$('element-detail').hidden=true;await loadElements();}}));
  root.querySelectorAll('[data-pipeline-download]').forEach(button=>button.addEventListener('click',()=>withAction(()=>downloadOutput(button.dataset.pipelineDownload))));
  window.addEventListener('storage',event=>{
    if(state.id&&event.key===key(context())){state.journal=readJournal({...context(),journal:null});renderConfiguration();renderRecovery();renderActionHistory();renderReview();updateBusy();}
  });
  objectPanel=createObjectInputsPanel({root:$('object-intake'),api,task,notify,getDossier,isBusy:()=>!!isBusy()||state.busy>0,
    onPrepared:async(value,dossierId)=>{if(state.id!==dossierId)return;await loadList();
      if(state.id===dossierId){await openOperation(value.plan.id);$('operation').scrollIntoView({block:'nearest'});}}});
  renderConfiguration();renderList();renderOperation();renderReview();updateBusy();
  return {
    configure(value){
      const workspaceId=value?.workspaceId??null,changed=workspaceId!==state.workspaceId;
      state.configured=value?.configured===true;state.workspaceId=workspaceId;state.source=value?.source??null;
      state.uploadLimitBytes=value?.uploadLimitBytes??33554432;
      objectPanel.configure(value);
      if(changed&&state.id)resetScope(state.id);else{renderConfiguration();updateBusy();}
      tab.hidden=false;
    },
    setDossier(view){
      objectPanel.setDossier(view);
      if((view?.id??null)!==state.id)resetScope(view?.id??null);
      renderQuestions();renderReview();updateBusy();
    },
    show(visible){
      void objectPanel.show(visible);
      const changed=visible!==state.shown;state.shown=visible;
      if(visible&&changed&&state.id){
        const ctx=context();state.busy++;updateBusy();
        refresh().catch(error=>{if(live(ctx))notify(friendly(error),'error');}).finally(()=>{state.busy--;updateBusy();});
      }
    },
    updateBusy
  };
}

/* Original research document review: neutral industrial surfaces. */
.document-layout{display:grid;grid-template-columns:minmax(200px,260px) minmax(0,1fr);gap:24px;align-items:start}
.document-history{border-right:1px solid #c7c7c7;padding-right:20px;min-width:0}
.document-history h3{font-size:14px;margin:18px 0 8px}
.document-item{display:flex;flex-direction:column;gap:5px;width:100%;text-align:left;overflow-wrap:anywhere;background:#fff;border:1px solid #c7c7c7;padding:10px;margin:0 0 8px;border-radius:2px}
.document-item.active{border-color:#292929;box-shadow:inset 3px 0 0 #292929}
.document-review{min-width:0}.document-review h3{overflow-wrap:anywhere}
.document-status{display:flex;gap:24px;border-top:1px solid #c7c7c7;border-bottom:1px solid #c7c7c7;margin:12px 0}
.document-status p{display:flex;flex-direction:column;gap:5px;font-size:13px;overflow-wrap:anywhere}
.document-receive-form{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:10px;margin:20px 0;padding:16px;background:#f4f4f4;border:1px solid #c7c7c7}
.document-receive-form .button-row,.document-receive-form p{grid-column:1/-1}
.document-filter{display:grid;grid-template-columns:minmax(100px,1fr) minmax(120px,1fr) minmax(140px,2fr) auto;align-items:end;gap:10px;margin:18px 0}
.document-filter label,.document-receive-form label{display:flex;flex-direction:column;gap:6px;font-size:13px;min-width:0}
.document-filter input,.document-filter select,.document-receive-form input,.document-receive-form select{width:100%;min-width:0}
.document-elements{display:flex;flex-direction:column;gap:8px}
.document-element{display:flex;flex-direction:column;gap:6px;width:100%;text-align:left;border:1px solid #c7c7c7;background:#fff;padding:12px;border-radius:2px;white-space:pre-wrap;overflow-wrap:anywhere}
.document-element:hover,.document-item:hover{background:#f4f4f4}
.document-element-detail{margin-top:20px;padding-top:16px;border-top:1px solid #c7c7c7;min-width:0}
.document-full-text,.document-review pre{white-space:pre-wrap;overflow-wrap:anywhere;word-break:normal;max-width:100%}
.document-full-text{font:inherit;font-size:14px;line-height:1.55;border:1px solid #c7c7c7;padding:14px;background:#f7f7f7}
@media(max-width:900px){.document-layout{grid-template-columns:1fr}.document-history{border-right:0;border-bottom:1px solid #c7c7c7;padding:0 0 16px}.document-filter{grid-template-columns:1fr 1fr}}
@media(max-width:520px){.document-filter,.document-receive-form{grid-template-columns:1fr}.document-status{flex-direction:column;gap:0}.document-status p{margin:8px 0}.document-layout{gap:14px}}

// MIT. Original document purchase and retained-edition review in the research operator.
const element=(tag,text,className)=>{
  const value=document.createElement(tag);if(text!==undefined)value.textContent=text;
  if(className)value.className=className;return value;
};
const array=value=>Array.isArray(value)?value:[];
const pretty=value=>JSON.stringify(value,null,2);
const same=(a,b)=>JSON.stringify(a)===JSON.stringify(b);
const bytes=value=>new Intl.NumberFormat().format(value)+' bytes';
const friendly=error=>({
  UNSTRUCTURED_RESPONSE_NOT_SAVED:'The original purchase has no completed saved document response yet. Open its existing buyer operation to inspect it.',
  UNSTRUCTURED_REVIEWED_EDITION_CHANGED:'The document edition changed. Refresh and review its current original record.',
  UNSTRUCTURED_RECEIVING_LABEL_CONFLICT:'This exact document is already received under a different label. Open that retained edition.',
  REVISION_CONFLICT:'The dossier changed after this decision was prepared. Refresh the dossier and review the receiving scope.',
})[error?.code]||error?.detail||error?.message||'The document operation could not complete.';

export function createUnstructuredPanel({root,tab,api,task,notify,getDossier,onReceived,isBusy}){
  root.innerHTML=`
    <div class="view-heading"><div><h2>Documents</h2><p class="muted">Review the original upload, processing profile and located document elements, then retain the edition with a research question.</p></div><button type="button" id="document-refresh">Refresh documents</button></div>
    <p id="document-source" class="muted small"></p>
    <div class="document-layout">
      <section class="document-history" aria-label="Document purchases and retained editions">
        <h3>Saved purchases</h3><div id="document-purchases"></div><button type="button" id="document-more" hidden>More purchases</button>
        <h3>Retained editions</h3><div id="document-editions"></div>
      </section>
      <section class="document-review" aria-label="Document review">
        <p id="document-empty" class="muted">Choose a completed purchase or an edition already retained in this dossier.</p>
        <div id="document-current" hidden>
          <h3 id="document-title"></h3><p id="document-summary" class="muted small"></p>
          <div class="document-status"><p><strong>Payment</strong><span id="document-payment"></span></p><p><strong>Output</strong><span id="document-output"></span></p></div>
          <div class="button-row"><button type="button" data-document-download="document">Original document</button><button type="button" data-document-download="response">Provider JSON</button><button type="button" data-document-download="edition">Research edition</button></div>
          <details class="original-record"><summary>Processing profile and original record</summary><pre id="document-profile"></pre></details>
          <p id="document-warnings" class="muted small"></p>
          <form id="document-receive-form" class="document-receive-form">
            <label>Research question<select id="document-question" required></select></label>
            <label>Edition label<input id="document-label" maxlength="240" required></label>
            <div class="button-row"><button type="submit" id="document-receive" class="primary">Retain reviewed document</button><button type="button" id="document-discard-pending" hidden>Review a new receiving decision</button></div>
            <p id="document-pending" class="muted small" role="status"></p><p class="form-error" hidden></p>
          </form>
          <p id="document-retained" class="muted small" hidden></p>
          <form id="document-filter" class="document-filter">
            <label>Page<select id="document-page"><option value="">All pages</option></select></label>
            <label>Element type<select id="document-type"><option value="">All types</option></select></label>
            <label>Text contains<input id="document-query" maxlength="2000" type="search"></label>
            <button type="submit">Filter elements</button>
          </form>
          <p id="document-element-count" class="muted small" role="status"></p>
          <div id="document-elements" class="document-elements"></div>
          <div class="pagination"><button type="button" id="document-prev">Previous</button><span id="document-page-label"></span><button type="button" id="document-next">Next</button></div>
          <section id="document-element-detail" class="document-element-detail" hidden></section>
        </div>
      </section>
    </div>
  `;
  const $=id=>root.querySelector('#'+id);
  const local={id:null,shown:false,configured:false,workspaceId:null,version:0,purchases:[],editions:[],
    next:null,current:null,records:null,offset:0,pending:null};
  const endpoint=suffix=>'/api/dossiers/'+encodeURIComponent(local.id)+'/unstructured'+(suffix||'');
  const pendingKey=()=> 'unstructured-receive:'+local.id;
  function savePending(value){
    local.pending=value;
    try {value?localStorage.setItem(pendingKey(),JSON.stringify(value)):localStorage.removeItem(pendingKey());}
    catch {notify('This browser could not retain the receiving decision across a restart. Keep this page open until its result returns.','error');}
  }
  function restorePending(){
    local.pending=null;
    try{const value=JSON.parse(localStorage.getItem(pendingKey())||'null');
      if(value&&value.dossierId===local.id&&value.input?.selection?.purchaseId)local.pending=value;
    }catch{}
  }
  async function withAction(action,form){
    return task(async()=>{try{return await action();}catch(error){error.detail=friendly(error);throw error;}},form);
  }
  function renderQuestions(){
    const selected=local.pending?.input?.questionId ?? $('document-question').value,view=getDossier();
    $('document-question').replaceChildren(...array(view?.questions).map(question=>{
      const option=element('option',question.text);option.value=question.id;return option;
    }));
    if(array(view?.questions).some(question=>question.id===selected))$('document-question').value=selected;
  }
  function renderList(){
    const button=(selection,title,subtitle)=>{
      const value=element('button',undefined,'document-item'+(same(selection,local.current?.selection)?' active':''));
      value.type='button';value.append(element('strong',title),element('span',subtitle,'muted small'));
      value.addEventListener('click',()=>withAction(()=>open(selection)));return value;
    };
    $('document-purchases').replaceChildren(...local.purchases.map(row=>button({purchaseId:row.id},
      row.intentId,row.profileId+' · '+row.state+' · '+row.outputStatus)));
    if(!local.purchases.length)$('document-purchases').append(element('p',local.configured?
      'Completed purchases from the configured original buyer appear here.':'Connect an original document buyer to receive new purchases.','muted small'));
    $('document-editions').replaceChildren(...local.editions.map(row=>button({editionId:row.id},
      row.label,(row.document?.filename||'Document')+' · '+
        (row.elementCount===null?'open to review':row.elementCount+' elements'))));
    if(!local.editions.length)$('document-editions').append(element('p','Retained document editions appear here.','muted small'));
    $('document-more').hidden=!local.next;
  }
  function renderCurrent(){
    const value=local.current;$('document-empty').hidden=!!value;$('document-current').hidden=!value;
    if(!value)return;
    $('document-title').textContent=value.document.filename;
    $('document-summary').textContent=bytes(value.document.bytes)+' · '+value.summary.elements+
      ' elements · '+value.summary.pages.length+' located pages · '+value.summary.withTableHtml+' table records';
    $('document-payment').textContent=value.native.status+
      (value.native.sellerReportedSettlement?' · '+value.native.sellerReportedSettlement:'');
    $('document-output').textContent=value.native.responseStatus+' · HTTP '+value.native.httpStatus;
    $('document-profile').textContent=pretty({profile:value.binding.profileId,parameters:value.parameters,
      document:value.document,originalPurchase:value.binding,editionSha256:value.editionSha256});
    $('document-warnings').textContent=array(value.warnings).join(' ');
    const retained=!!value.retained;$('document-receive-form').hidden=retained&&!local.pending;
    $('document-retained').hidden=!retained;
    $('document-retained').textContent=retained?'Retained as '+value.retained.label+
      '. Evidence selection, notes and findings remain in this dossier.':'';
    const pending=local.pending?.input;
    if(pending){
      $('document-label').value=pending.label;
      if(array(getDossier()?.questions).some(question=>question.id===pending.questionId))$('document-question').value=pending.questionId;
    }
    const pendingQuestion=pending&&array(getDossier()?.questions).find(question=>question.id===pending.questionId);
    $('document-pending').textContent=pending?'Saved decision: '+pending.label+' → '+
      (pendingQuestion?.text||pending.questionId)+'. Original purchase '+pending.selection.purchaseId+
      ', reviewed edition '+pending.expectedEditionSha256+'. Retry recovers this exact decision.':'';
    $('document-discard-pending').hidden=!local.pending;
    $('document-receive').textContent=local.pending?'Retry saved receiving decision':'Retain reviewed document';
    $('document-question').disabled=!!local.pending||isBusy();
    $('document-label').disabled=!!local.pending||isBusy();
    $('document-receive').disabled=isBusy()||(!local.pending&&!$('document-question').value);
    $('document-prev').disabled=isBusy()||local.offset===0;
    $('document-next').disabled=isBusy()||!local.records||local.records.nextOffset===null;
  }
  function showElement(row){
    const target=$('document-element-detail'),value=row.element;target.hidden=false;
    target.replaceChildren(element('h3',(value.type??'Element')+' '+row.position),
      element('p','Original ID: '+value.element_id,'muted small'),element('pre',value.text,'document-full-text'));
    const metadata=element('details',undefined,'original-record');metadata.append(element('summary','Page, coordinates and original metadata'),
      element('pre',pretty(value.metadata)));target.append(metadata);
    if(typeof value.metadata.text_as_html==='string'){
      const table=element('details',undefined,'original-record');
      table.append(element('summary','Original table HTML'),element('pre',value.metadata.text_as_html));target.append(table);
    }
  }
  function renderRecords(){
    const value=local.records;if(!value)return;
    $('document-element-count').textContent=value.filtered+' of '+value.total+' elements match the current filters.';
    $('document-elements').replaceChildren(...value.items.map(row=>{
      const button=element('button',undefined,'document-element');button.type='button';
      button.append(element('span','#'+row.position+' · '+(row.element.type??'Element')+
        (row.element.metadata.page_number===undefined?'':' · page '+row.element.metadata.page_number),'muted small'),
        element('span',row.element.text.length>480?row.element.text.slice(0,480)+'…':row.element.text));
      button.addEventListener('click',()=>showElement(row));return button;
    }));
    if(!value.items.length)$('document-elements').append(element('p','No document elements match these filters.','muted'));
    $('document-page-label').textContent='Page '+(Math.floor(local.offset/25)+1)+' of '+Math.max(1,Math.ceil(value.filtered/25));
    renderCurrent();
  }
  async function loadElements(){
    if(!local.current)return;
    const version=local.version,selection=local.current.selection,sha=local.current.editionSha256;
    const value=await api(endpoint('/elements'),{method:'POST',body:{selection,expectedEditionSha256:sha,
      offset:local.offset,limit:25,page:$('document-page').value,type:$('document-type').value,query:$('document-query').value}});
    if(version!==local.version||!same(selection,local.current?.selection)||sha!==local.current?.editionSha256)return;
    local.records=value;renderRecords();
  }
  async function open(selection){
    const version=++local.version;
    const value=await api(endpoint('/review'),{method:'POST',body:{selection}});
    if(version!==local.version)return;
    local.current=value;local.offset=0;local.records=null;
    $('document-element-detail').hidden=true;$('document-query').value='';
    $('document-page').replaceChildren(element('option','All pages'),...value.summary.pages.map(page=>{
      const option=element('option','Page '+page);option.value=page;return option;
    }));$('document-page').options[0].value='';
    $('document-type').replaceChildren(element('option','All types'),...Object.keys(value.summary.types).map(type=>{
      const option=element('option',type);option.value=type;return option;
    }));$('document-type').options[0].value='';
    $('document-label').value=value.retained?.label||(value.document.filename+' · '+value.binding.profileId).slice(0,240);
    renderQuestions();renderList();renderCurrent();await loadElements();
  }
  async function loadList(more=false){
    if(!local.id)return;
    const version=local.version,value=await api(endpoint('')+(more&&local.next?'?after='+encodeURIComponent(local.next):''));
    if(version!==local.version)return;
    local.purchases=more?[...local.purchases,...value.purchases]:value.purchases;local.editions=value.editions;
    local.next=value.nextAfter;local.configured=value.configured;local.workspaceId=value.workspaceId;
    $('document-source').textContent=value.configured?'Original buyer workspace: '+value.workspaceId:
      'Retained documents reopen from this dossier and its portable archive.';
    renderList();renderCurrent();
  }
  async function refresh(){const version=local.version;await loadList();if(version!==local.version)return;if(local.current)await open(local.current.selection);}
  $('document-refresh').addEventListener('click',()=>withAction(refresh));
  $('document-more').addEventListener('click',()=>withAction(()=>loadList(true)));
  $('document-filter').addEventListener('submit',event=>{event.preventDefault();withAction(async()=>{
    local.offset=0;$('document-element-detail').hidden=true;await loadElements();
  });});
  $('document-prev').addEventListener('click',()=>withAction(async()=>{local.offset=Math.max(0,local.offset-25);await loadElements();}));
  $('document-next').addEventListener('click',()=>withAction(async()=>{if(Number.isSafeInteger(local.records?.nextOffset)){local.offset=local.records.nextOffset;await loadElements();}}));
  $('document-question').addEventListener('change',renderCurrent);
  $('document-receive-form').addEventListener('submit',event=>{
    event.preventDefault();withAction(async()=>{
      if(!local.pending){
        const view=getDossier();
        savePending({dossierId:local.id,input:{selection:local.current.selection,
          expectedEditionSha256:local.current.editionSha256,questionId:$('document-question').value,
          label:$('document-label').value,expectedRevision:view.revision}});
      }
      const original=local.pending;
      const result=await api(endpoint('/receive'),{method:'POST',body:original.input});
      if(local.pending===original)savePending(null);
      await onReceived(result.dossier);await loadList();await open({editionId:result.editionId});
      notify((result.reused?'Recovered the original receiving result':'Document retained')+
        ' in dossier revision '+result.dossier.revision+'.');
    },event.currentTarget);
  });
  $('document-discard-pending').addEventListener('click',()=>withAction(async()=>{
    await loadList();savePending(null);
    if(local.current)$('document-label').value=local.current.retained?.label||
      (local.current.document.filename+' · '+local.current.binding.profileId).slice(0,240);
    renderQuestions();renderCurrent();
  }));
  root.querySelectorAll('[data-document-download]').forEach(button=>button.addEventListener('click',()=>withAction(async()=>{
    const value=local.current,response=await api(endpoint('/download'),{method:'POST',download:true,
      body:{selection:value.selection,expectedEditionSha256:value.editionSha256,file:button.dataset.documentDownload}});
    const blob=await response.blob(),url=URL.createObjectURL(blob),link=element('a');
    link.href=url;const match=/filename="([^"]+)"/.exec(response.headers.get('content-disposition')||'');
    link.download=match?.[1]||value.document.filename;document.body.append(link);link.click();link.remove();
    setTimeout(()=>URL.revokeObjectURL(url),30000);
  })));
  return {
    configure(value){local.configured=value?.configured===true;local.workspaceId=value?.workspaceId??null;tab.hidden=false;},
    setDossier(view){
      if(view?.id!==local.id){local.id=view?.id??null;local.version++;local.purchases=[];local.editions=[];
        local.current=null;local.records=null;local.next=null;local.offset=0;restorePending();renderList();renderCurrent();}
      renderQuestions();renderCurrent();
    },
    show(visible){const changed=visible!==local.shown;local.shown=visible;
      if(visible&&changed&&local.id)refresh().catch(error=>notify(friendly(error),'error'));},
    updateBusy(){renderCurrent();}
  };
}

// MIT. Small original-Research navigation control; no second Dossier state.
export function installZoteroResearchControl({container,open,status,onError=()=>{}}) {
  let disposed=false,busy=false,epoch=0;
  const section=document.createElement('section'),title=document.createElement('h2'),description=document.createElement('p');
  title.textContent='Zotero library sources';
  description.textContent='Capture or receive an original Zotero library edition, review its collection project, and return a complete source bundle to this Research workspace.';
  const button=document.createElement('button');button.type='button';button.textContent='Open Zotero library workspace';
  const target=document.createElement('div');
  section.append(title,description,button,target);container.append(section);
  button.onclick=async()=>{
    if(disposed||busy)return;busy=true;button.disabled=true;const selectedEpoch=epoch;
    try{
      const result=await open();
      if(disposed||selectedEpoch!==epoch)return;
      const url=new URL(result.url);
      if(!result.active||url.protocol!=='http:'||url.hostname!=='127.0.0.1'||!url.port||url.pathname!=='/'||
        url.search||url.username||url.password||!/^#token=[a-f0-9]{64}$/.test(url.hash))throw new Error('Zotero workspace connection is not current.');
      const link=document.createElement('a');link.href=url.href;link.target='_blank';link.rel='noopener';link.textContent='Continue in Zotero workspace';
      target.replaceChildren(link);
    }catch(error){if(!disposed)onError(error);}finally{busy=false;if(!disposed)button.disabled=false;}
  };
  async function refresh(){
    const selectedEpoch=++epoch,result=await status();
    if(disposed||selectedEpoch!==epoch)return;
    section.hidden=!result.configured;target.replaceChildren();
  }
  return {refresh,profileChanged(){epoch++;target.replaceChildren();},dispose(){disposed=true;epoch++;target.replaceChildren();section.remove();}};
}

// MIT — Reports contain retained source material and the analyst's own work.
import {eligibilityMarkdown,eligibilityHtml} from './eligibility-review.mjs';
import {extractionMarkdown,extractionHtml} from './study-extraction-report.mjs';
import {riskOfBiasMarkdown,riskOfBiasHtml} from './risk-of-bias/report.mjs';
import {extractionPublicationMarkdownLines,extractionPublicationHtmlFragment} from './extraction-publication.mjs';
import {hasOriginalFiles,reportSourceRecord,originalFilesMarkdown,originalFilesHtml} from './source-file-reports.mjs';
const escape = value => String(value ?? '').replace(/[&<>"']/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[char]);
const md = value => String(value ?? '').replace(/[\\\x60*_{}\[\]<>#+!|]/g, '\\$&');
const rendered = value => typeof value === 'string' ? value : JSON.stringify(value, null, 2);
const url = value => { try { const parsed = new URL(value); return ['http:', 'https:'].includes(parsed.protocol) ? parsed.href : ''; } catch { return ''; } };
const link = (label, target) => { const href = url(target); return href ? '<a href="' + escape(href) + '" rel="noreferrer">' + escape(label) + '</a>' : escape(label); };
const occurrenceRecords = source => source.citations.map(citation => ({
  occurrenceId: citation.occurrenceId, editionId: citation.editionId,
  questionId: citation.questionId, key: citation.key,
  original: reportSourceRecord(citation.original,source.variants.find(variant=>variant.contentDigest===citation.contentDigest)?.content),
}));
function includedSources(view) {
  const references = new Set(view.findings.flatMap(finding => finding.sourceIds));
  return view.sources.filter(source => source.selected || references.has(source.id));
}
function analystNotes(view) {
  const unique = new Map();
  for (const selection of view.unavailableSelections ?? []) {
    if (!selection.note && !selection.selected) continue;
    const key = selection.questionId + '\n' + selection.editionId + '\n' + selection.note;
    if (!unique.has(key)) unique.set(key, selection);
  }
  return [...unique.values()];
}
function fence(value) {
  const content = rendered(value);
  let width = 3;
  for (const run of content.matchAll(/\x60+/g)) width = Math.max(width, run[0].length + 1);
  const marker = '\x60'.repeat(width);
  return marker + (typeof value === 'string' ? 'text' : 'json') + '\n' + content + '\n' + marker;
}


function citationReviewMarkdown(view){
  if(!(view.citationUpdates?.length||view.citationReviews?.length))return [];
  const lines=['## Citation update review','',
    'These notices are linked to the DOI records retained in this dossier. Each disposition records the reviewer and the exact report revisions.','',
    '| Notice | Updated work | Type | Review |','| --- | --- | --- | --- |'];
  for(const notice of view.citationUpdates??[])
    lines.push('| '+[notice.noticeDoi,notice.targetDoi,notice.type,notice.status].map(md).join(' | ')+' |');
  for(const review of view.citationReviews??[]){
    lines.push('','### '+md(review.notice.title),'',md(review.notice.noticeDoi)+' updates '+md(review.notice.targetDoi)+'.','',
      'Reviewer: '+md(review.actor)+' · '+md(review.createdAt)+' · Decision: '+md(review.decision),'',
      'Original report revision '+review.originalRevision+' → reviewed report revision '+review.revision+'.','',
      review.reason,'','Source edition: '+md(review.notice.latestSource.editionId)+
        ' · Retained edition SHA-256: '+md(review.notice.latestSource.sourceSha256),'',
      '#### Original notice and capture bindings','',fence(review.notice),'');
    for(const disposition of review.findingDispositions)
      lines.push('- Finding '+md(disposition.findingId)+': '+md(disposition.disposition)+'. '+md(disposition.reason),'');
    for(const change of review.changes.evidence)
      lines.push('Evidence '+md(change.occurrenceId)+':','',fence({before:change.before,after:change.after}),'');
    for(const change of review.changes.findings)
      lines.push('Finding '+md(change.findingId)+':','',
        '**Previous finding: '+md(change.before.title)+'**','',change.before.text,'','Citations: '+change.before.occurrenceIds.map(md).join(', '),'',
        '**Reviewed finding: '+md(change.after.title)+'**','',change.after.text,'','Citations: '+change.after.occurrenceIds.map(md).join(', '),'');
  }
  lines.push('','### Retained update acquisition coverage','');
  for(const item of view.citationCoverage??[])lines.push('- '+md(item.label)+': '+md(item.coverage)+
    '; updates '+md(item.updatesLookup)+(item.issues.length?'; '+item.issues.map(md).join(', '):'')+'.','');
  return lines;
}
function citationReviewHtml(view){
  if(!(view.citationUpdates?.length||view.citationReviews?.length))return '';
  const notices=(view.citationUpdates??[]).map(value=>'<tr><td>'+link(value.noticeDoi,'https://doi.org/'+encodeURIComponent(value.noticeDoi))+
    '</td><td>'+link(value.targetDoi,'https://doi.org/'+encodeURIComponent(value.targetDoi))+'</td><td>'+escape(value.type)+
    '</td><td>'+escape(value.status)+'</td></tr>').join('');
  const reviews=(view.citationReviews??[]).map(review=>'<article><h3>'+escape(review.notice.title)+'</h3>'+
    '<p>'+escape(review.notice.noticeDoi)+' updates '+escape(review.notice.targetDoi)+'</p>'+
    '<p class="muted">Reviewer: '+escape(review.actor)+' · '+escape(review.createdAt)+' · '+escape(review.decision)+'</p>'+
    '<p>Original report revision '+review.originalRevision+' → reviewed report revision '+review.revision+'</p>'+
    '<div class="prose">'+escape(review.reason)+'</div>'+
    '<p class="file-identity">Source edition: '+escape(review.notice.latestSource.editionId)+
    ' · Retained edition SHA-256: '+escape(review.notice.latestSource.sourceSha256)+'</p>'+
    review.findingDispositions.map(value=>'<p><strong>'+escape(value.findingId)+': '+escape(value.disposition)+
      '</strong></p><div class="prose">'+escape(value.reason)+'</div>').join('')+
    review.changes.findings.map(change=>'<details open><summary>Finding '+escape(change.findingId)+'</summary>'+
      '<h4>Previous finding: '+escape(change.before.title)+'</h4><div class="prose">'+escape(change.before.text)+'</div><p class="file-identity">'+escape(change.before.occurrenceIds.join(', '))+'</p>'+
      '<h4>Reviewed finding: '+escape(change.after.title)+'</h4><div class="prose">'+escape(change.after.text)+'</div><p class="file-identity">'+escape(change.after.occurrenceIds.join(', '))+'</p></details>').join('')+
    (review.changes.evidence.length?'<details><summary>Evidence changes</summary><pre>'+escape(JSON.stringify(review.changes.evidence,null,2))+'</pre></details>':'')+
    '<details><summary>Original notice and response bindings</summary><pre>'+escape(JSON.stringify(review.notice,null,2))+'</pre></details></article>').join('');
  const coverage=(view.citationCoverage??[]).map(value=>'<li>'+escape(value.label)+': '+escape(value.coverage)+
    '; updates '+escape(value.updatesLookup)+(value.issues.length?'; '+escape(value.issues.join(', ')):'')+'</li>').join('');
  return '<section><h2>Citation update review</h2><p>These notices are linked to the DOI records retained in this dossier. Each disposition keeps its reviewer and original report revisions.</p>'+
    '<div class="table"><table><thead><tr><th>Notice</th><th>Updated work</th><th>Type</th><th>Review</th></tr></thead><tbody>'+notices+
    '</tbody></table></div>'+reviews+'<details><summary>Retained update acquisition coverage</summary><ul>'+coverage+'</ul></details></section>';
}

export function markdownReport(view) {
  const sources = includedSources(view), numbering = new Map(sources.map((source, index) => [source.id, index + 1]));
  const lines = ['# ' + md(view.title), '', view.description, '',
    'Revision ' + view.revision + ' · ' + view.updatedAt, '', '## Research questions', ''];
  for (const question of view.questions) {
    lines.push('### ' + md(question.text), '', 'Status: ' + question.status, '');
    if (question.notes) lines.push(question.notes, '');
    for (const finding of view.findings.filter(row => row.questionId === question.id)) {
      const references = finding.sourceIds.map(id => numbering.get(id)).filter(Boolean).map(number => '[' + number + ']').join(' ');
      lines.push('#### ' + md(finding.title), '', finding.text, '', references, '');
      if (finding.unavailableSources) lines.push('Original edition references: ' + finding.occurrenceIds.join(', '), '');
    }
  }
  lines.push('## Selected sources', '');
  if (!sources.length) lines.push('No retained sources selected for this report.', '');
  for (const [index, source] of sources.entries()) {
    lines.push('### [' + (index + 1) + '] ' + md(source.title), '');
    if (url(source.url)) lines.push('<' + url(source.url).replace(/>/g, '%3E') + '>', '');
    if (source.authors.length) lines.push('Authors: ' + source.authors.map(md).join('; '), '');
    lines.push('Provider: ' + md(source.provider) + (source.publishedAt ? ' · Published: ' + md(source.publishedAt) : ''), '');
    lines.push('Assessment: ' + source.classification, '');
    if (source.note) lines.push(source.note, '');
    for (const variant of source.variants) {
      lines.push('Edition ' + variant.editionId, '', originalFilesMarkdown(variant.content) ?? fence(variant.content), '');
    }
    lines.push('Original occurrences: ' + source.citations.map(citation => citation.editionId + '/' + citation.key).join(', '), '');
    lines.push(source.variants.some(variant=>hasOriginalFiles(variant.content)) ? 'Source records and original-file references:' : 'Original source records:', '', fence(occurrenceRecords(source)), '');
  }
  const notes = analystNotes(view);
  if (notes.length) {
    lines.push('## Notes attached to original edition references', '');
    for (const note of notes) lines.push('- ' + md(note.editionId + '/' + note.key) + ' · ' + note.classification +
      (note.note ? '\n\n' + note.note : ''), '');
  }
  lines.push(...citationReviewMarkdown(view));
  lines.push(...eligibilityMarkdown(view.eligibility));
  lines.push(...extractionMarkdown(view.extraction));
  lines.push(...extractionPublicationMarkdownLines(view.extractionPublications));
  lines.push(...riskOfBiasMarkdown(view.riskOfBias));
  lines.push('## Editions and source usage', '',
    '| Edition | Provider | Storage | Status | Source observations |',
    '| --- | --- | --- | --- | --- |');
  for (const edition of view.editions) lines.push('| ' + [edition.label, edition.provider, edition.mode,
    edition.status, JSON.stringify(edition.usage)].map(value => md(value).replace(/\n/g, ' ')).join(' | ') + ' |');
  lines.push('', '## Source terms and original operation references', '');
  for (const edition of view.editions) {
    lines.push('- ' + md(edition.label) + ': ' + md(edition.sourceTerms ?? 'Original edition access') +
      (edition.sourceReference ? ' · ' + md(edition.sourceReference) : ''), '');
    if (edition.reference) lines.push(fence(edition.reference), '');
    if (edition.origin) lines.push(fence(edition.origin), '');
  }
  return lines.join('\n') + '\n';
}

export function htmlReport(view) {
  const sources = includedSources(view), numbers = new Map(sources.map((source, index) => [source.id, index + 1]));
  const questions = view.questions.map(question => '<section><h2>' + escape(question.text) +
    '</h2><p class="muted">Status: ' + escape(question.status) + '</p>' +
    (question.notes ? '<div class="prose">' + escape(question.notes) + '</div>' : '') +
    view.findings.filter(row => row.questionId === question.id).map(finding =>
      '<article><h3>' + escape(finding.title) + '</h3><div class="prose">' + escape(finding.text) +
      '</div><p>' + finding.sourceIds.filter(id => numbers.has(id)).map(id =>
        '<a href="#source-' + numbers.get(id) + '">[' + numbers.get(id) + ']</a>').join(' ') + '</p>' +
      (finding.unavailableSources ? '<details><summary>Original edition references</summary><pre>' +
        escape(finding.occurrenceIds.join('\n')) + '</pre></details>' : '') + '</article>').join('') + '</section>').join('');
  const sourceHtml = sources.map((source, index) => '<article id="source-' + (index + 1) + '"><h3>[' +
    (index + 1) + '] ' + link(source.title, source.url) + '</h3><p class="muted">' +
