      Number.isSafeInteger(pin.expectedRevision)&&pin.expectedRevision>=1&&pin.sourceRevision===pin.expectedRevision&&
      SHA.test(pin.stateSha256??'')&&typeof pin.stateBase64==='string'&&Array.isArray(pin.captureIds)&&
