    previewRepricing:input=>model.previewRepricing(copy(input)),
    saveRepricing:input=>model.saveRepricing(copy(input)),
    stageRepricing:input=>model.stageRepricing(copy(input))};
}

// MIT. One Linux delivery writer per original SF98 outbox.
import { spawn } from 'node:child_process';
import { randomUUID } from 'node:crypto';
import { constants } from 'node:fs';
import { lstat, open, realpath } from 'node:fs/promises';
import { hostname } from 'node:os';
import { isAbsolute, join, resolve } from 'node:path';

const holders = new WeakMap();
const LOCK_NAME = '.sf98-delivery.lock';
const CONFLICT = 75;

async function privateDirectory(directory) {
  if (typeof directory !== 'string' || !isAbsolute(directory) ||
      directory === '/' || resolve(directory) !== directory ||
      await realpath(directory) !== directory) throw new Error('PRIVATE_OUTBOX_PATH_REQUIRED');
  const info = await lstat(directory);
  if (!info.isDirectory() || info.mode & 0o077) throw new Error('PRIVATE_OUTBOX_MODE_REQUIRED_0700');
}

async function lockFile(directory, create) {
  await privateDirectory(directory);
  const handle = await open(join(directory, LOCK_NAME), constants.O_RDWR |
    (create ? constants.O_CREAT : 0) | (constants.O_NOFOLLOW ?? 0), 0o600);
  try {
    const info = await handle.stat();
    if (!info.isFile() || info.nlink !== 1 || info.mode & 0o077)
      throw new Error('PRIVATE_DELIVERY_LOCK_REQUIRED_0600');
    return { handle, info };
  } catch (error) { await handle.close(); throw error; }
}

async function flock(handle) {
  if (process.platform !== 'linux') throw new Error('SF98_DELIVERY_REQUIRES_LINUX_FLOCK');
  // flock(2) belongs to the open file description. FD 3 is a dup of our still
  // open handle, so the kernel lock survives this short helper's exit and is
  // released by handle.close(), or automatically if this process is killed.
  return new Promise((resolvePromise, reject) => {
    const child = spawn('flock', ['--exclusive', '--nonblock',
      '--conflict-exit-code', String(CONFLICT), '3'], {
      stdio: ['ignore', 'ignore', 'ignore', handle.fd], shell: false,
    });
    const timer = setTimeout(() => child.kill('SIGKILL'), 5000);
    child.once('error', () => {
      clearTimeout(timer);
      reject(new Error('SF98_FLOCK_UNAVAILABLE_INSTALL_UTIL_LINUX'));
    });
    child.once('exit', code => {
      clearTimeout(timer);
      if (code === 0) resolvePromise(true);
      else if (code === CONFLICT) resolvePromise(false);
      else reject(new Error('SF98_DELIVERY_LOCK_HELPER_FAILED'));
    });
  });
}

export async function acquireDeliveryLease(directory, { purpose = 'drain' } = {}) {
  if (!['worker', 'drain', 'requeue'].includes(purpose)) throw new TypeError('Invalid delivery lease purpose');
  const { handle, info } = await lockFile(directory, true);
  try {
    if (!await flock(handle)) {
      const error = new Error('SF98_DELIVERY_BUSY');
      error.code = 'SF98_DELIVERY_BUSY';
      throw error;
    }
    const owner = Object.freeze({ schema: 'stellar-forge.sf98.delivery-owner.v1',
      id: randomUUID(), pid: process.pid, host: hostname(), purpose,
      acquiredAt: new Date().toISOString() });
    await handle.truncate(0);
    await handle.writeFile(JSON.stringify(owner) + '\n');
    await handle.sync();
    const lease = Object.freeze({ directory, owner,
      async release() {
        const held = holders.get(lease);
        if (!held) return;
        holders.delete(lease);
        await held.handle.close();
      },
    });
    holders.set(lease, { handle, info, directory });
    await assertDeliveryLease(lease, directory);
    return lease;
  } catch (error) { await handle.close(); throw error; }
}

export async function assertDeliveryLease(lease, directory) {
  const held = holders.get(lease);
  if (!held || held.directory !== directory) throw new Error('SF98_ACTIVE_DELIVERY_LEASE_REQUIRED');
  const current = await lstat(join(directory, LOCK_NAME));
  if (!current.isFile() || current.dev !== held.info.dev || current.ino !== held.info.ino || current.nlink !== 1)
    throw new Error('SF98_DELIVERY_LOCK_REPLACED');
}

export async function withDeliveryLease(directory, operation, options) {
  const lease = await acquireDeliveryLease(directory, options);
  try { return await operation(lease); }
  finally { await lease.release(); }
}

export async function inspectDeliveryLease(directory) {
  let file;
  try { file = await lockFile(directory, false); }
  catch (error) {
    if (error.code === 'ENOENT') return { active: false, owner: null };
    throw error;
  }
  try {
    const available = await flock(file.handle);
    let owner = null;
    if ((await file.handle.stat()).size <= 4096) {
      try {
        const raw = JSON.parse(await file.handle.readFile('utf8'));
        if (raw.schema === 'stellar-forge.sf98.delivery-owner.v1') owner = raw;
      } catch { /* owner may be writing metadata; kernel ownership remains authoritative */ }
    }
    return { active: !available, owner };
  } finally { await file.handle.close(); }
}

// MIT. Selected-event recovery through the original SF98 outbox and lease.
import { createHash } from 'node:crypto';
import { assertDeliveryLease, withDeliveryLease } from './delivery-lock.mjs';

const identifier = value => typeof value === 'string' && /^[a-f0-9]{64}$/.test(value);
const problem = (code,status=409) => Object.assign(new Error(code),{code,status});

/** This revision identifies the exact original delivery state, not a second
 * journal or application-level generation. A later exhausted cycle differs. */
export function deliveryRevision(row) {
  if (!identifier(row?.event?.id)) throw problem('DELIVERY_EVENT_INVALID',400);
  return createHash('sha256').update(JSON.stringify({id:row.event.id,state:row.state ?? null})).digest('hex');
}

export async function inspectDelivery(outbox,id) {
  if (!identifier(id) || typeof outbox?.rows !== 'function') throw problem('DELIVERY_EVENT_INVALID',400);
  const row = (await outbox.rows()).find(candidate => candidate.event.id === id);
  if (!row) throw problem('DELIVERY_EVENT_NOT_FOUND',404);
  return {row,revision:deliveryRevision(row)};
}

/** The receiver-workspace controller may pause and await ITS OWN native
 * worker before calling this, then resume that same pinned receiver profile.
 * An unrelated worker keeps its original kernel lease and is never signalled.
 * Only the original notification is requeued; this cannot invoke a payment. */
export async function requeueDelivery(outbox,{id,expectedRevision,lease}) {
  if (!identifier(id) || !identifier(expectedRevision) || typeof outbox?.requeue !== 'function')
    throw problem('DELIVERY_RECOVERY_INPUT_INVALID',400);
  try {
    const recover = async currentLease => {
      await assertDeliveryLease(currentLease,outbox.dir);
      const before = await inspectDelivery(outbox,id);
      if (before.revision !== expectedRevision) throw problem('DELIVERY_STATE_CHANGED');
      if (before.row.state?.state !== 'EXHAUSTED') throw problem('DELIVERY_NOT_EXHAUSTED');
      await outbox.requeue(id);
      const after = await inspectDelivery(outbox,id);
      return {schema:'stellar-forge.sf98.delivery-recovery.v1',id,
        previousRevision:before.revision,revision:after.revision,
        state:after.row.state.state,orderReference:after.row.event.orderReference ?? null,
        recordedAt:after.row.state.at,deliveryAttempted:false,paymentAttempted:false};
    };
    return lease === undefined ? await withDeliveryLease(outbox.dir,recover,{purpose:'requeue'}) : await recover(lease);
  } catch (error) {
    if (error.code === 'SF98_DELIVERY_BUSY') throw problem('DELIVERY_WORKER_ACTIVE');
    throw error;
  }
}

// MIT. Native x402 settlement -> durable minimal merchant delivery event.
// This does not verify payments: ONLY the original SF30 native server can do so.
import { createHash } from 'node:crypto';
import { constants } from 'node:fs';
import { mkdir, open, readFile, stat } from 'node:fs/promises';
import { isAbsolute, join, resolve } from 'node:path';
import { selectServiceRoute } from '../sf30-seller-sdk/route-path.mjs';
import { supportsSellerMethod } from '../sf30-seller-sdk/http-methods.mjs';

export const SCHEMA = 'stellar-forge.sf98.delivery-event.v1';
const hash = x => createHash('sha256').update(x).digest('hex');
const okId = x => typeof x === 'string' && /^[a-f0-9]{64}$/.test(x);
const date = () => new Date().toISOString();
const nativeInstrumentations = new WeakMap();

/** Original embedding metadata for a later managed launcher. Payment callers
 * receive the same server; observers see only the original journal warning. */
export function inspectNativeSettlementInstrumentation(server) {
  const held = nativeInstrumentations.get(server);
  if (!held) return null;
  return Object.freeze({ server, outbox: held.outbox,
    observeWriteFailures(listener) {
      if (typeof listener !== 'function') throw new TypeError('Native delivery warning observer required');
      held.observers.add(listener); return () => held.observers.delete(listener);
    } });
}

function parseLine(line, path, index) {
  let data;
  try { data = JSON.parse(line); } catch { throw new Error('CORRUPT_JOURNAL:' + path + ':' + index); }
  if (!data || typeof data !== 'object' || !okId(data.id)) throw new Error('INVALID_JOURNAL_RECORD:' + path + ':' + index);
  return data;
}
async function loadLines(path) {
  let data;
  try { data = await readFile(path, 'utf8'); }
  catch (e) { if (e.code === 'ENOENT') return []; throw e; }
  if (data && !data.endsWith('\n')) throw new Error('TRUNCATED_JOURNAL:' + path);
  return data.split('\n').filter(Boolean).map((x, i) => parseLine(x, path, i + 1));
}
async function append(dir, name, row) {
  const path = join(dir, name);
  const flags = constants.O_APPEND | constants.O_CREAT | constants.O_WRONLY | (constants.O_NOFOLLOW ?? 0);
  const handle = await open(path, flags, 0o600);
  try {
    const meta = await handle.stat();
    if (!meta.isFile() || (meta.mode & 0o077) !== 0) throw new Error('PRIVATE_JOURNAL_REQUIRED:' + name);
    const bytes = Buffer.from(JSON.stringify(row) + '\n');
    if (bytes.length > 8192) throw new RangeError('JOURNAL_RECORD_TOO_LARGE');
    // One append per record; a single operator process owns this directory.
    const { bytesWritten } = await handle.write(bytes);
    if (bytesWritten !== bytes.length) throw new Error('SHORT_JOURNAL_WRITE');
    await handle.sync();
  } finally { await handle.close(); }
}
function receiptFromSuccess(settled, payment) {
  const headers = settled?.headers;
